#!/usr/bin/env python3
"""Build a single-file candidate: incumbent main.py plus the SE wheat add-on.

The incumbent source is kept verbatim. FQ4 and the add-on run in their own
module namespaces; the new entry point is defined last so Kaggle selects it.
"""
from __future__ import annotations
import argparse, json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

WRAPPER = '''

# ---- SE wheat add-on (generated by scripts/build_se_addon.py) ----
import types as _se_types
_SE_FQ4 = _se_types.ModuleType("fq4_embedded")
exec(compile({fq4!r}, "fq4_embedded", "exec"), _SE_FQ4.__dict__)
_SE_MOD = _se_types.ModuleType("se_addon_embedded")
exec(compile({addon!r}, "se_addon_embedded", "exec"), _SE_MOD.__dict__)
_SE_CONFIG = {config!r}
_SE_INCUMBENT = agent
_SE_BOTS = {{}}


def se_addon_agent(observation, configuration=None):
    me = int(_SE_FQ4.g(observation, "player", 0))
    step = int(_SE_FQ4.g(observation, "step", 0))
    bot = _SE_BOTS.get(me)
    if bot is None or step == 0:
        bot = _SE_MOD.SEAddon(_SE_FQ4, _SE_INCUMBENT, _SE_CONFIG)
        _SE_BOTS[me] = bot
    return bot.act(observation, configuration)
'''


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--incumbent", default=str(ROOT / "main.py"))
    p.add_argument("--config", default="{}")
    p.add_argument("--output", required=True)
    a = p.parse_args()
    out = Path(a.incumbent).read_text() + WRAPPER.format(
        fq4=(ROOT / "agents/fq4.py").read_text(),
        addon=(ROOT / "agents/se_addon.py").read_text(),
        config=json.loads(a.config))
    Path(a.output).parent.mkdir(parents=True, exist_ok=True)
    Path(a.output).write_text(out)
    print("wrote", a.output, len(out))


if __name__ == "__main__":
    main()
